package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.relatorio.RelatorioContribuicaoRepository; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RelatorioContribuicaoApplicationService { private final RelatorioContribuicaoRepository repo; private final SegurancaOrganizacaoService seguranca; public RelatorioContribuicaoApplicationService(RelatorioContribuicaoRepository r,SegurancaOrganizacaoService s){repo=r;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioContribuicaoItem> contribuicoes(RelatorioContribuicaoFiltro f){validar(f);var p=repo.registros(f.organizacaoUuid(),f.dataInicio(),f.dataFim(),tipo(f),f.categoriaUuid(),pessoa(f),PageRequest.of(pagina(f),tamanho(f)));var itens=p.getContent().stream().map(x->new RelatorioContribuicaoItem(x.getUuid(),x.getData(),x.getTipo(),x.getCategoria(),x.getContribuinte(),x.getValor(),x.getMeioRecebimento(),x.getDestinacao())).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),p.getTotalElements(),p.getTotalPages(),"data","desc");}
 @Transactional(readOnly=true) public RelatorioContribuicaoResumo resumo(RelatorioContribuicaoFiltro f){validar(f);var r=repo.resumo(f.organizacaoUuid(),f.dataInicio(),f.dataFim(),tipo(f),f.categoriaUuid(),pessoa(f));return new RelatorioContribuicaoResumo(r.getTotalContribuicoes(),r.getValorTotal());}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioContribuicaoDizimistaItem> porDizimista(RelatorioContribuicaoFiltro f){validar(f);var p=repo.porDizimista(f.organizacaoUuid(),f.dataInicio(),f.dataFim(),f.categoriaUuid(),pessoa(f),PageRequest.of(pagina(f),tamanho(f)));var itens=p.getContent().stream().map(x->new RelatorioContribuicaoDizimistaItem(x.getPessoaUuid(),x.getPessoa(),x.getQuantidade(),x.getValorTotal(),x.getUltimaContribuicao())).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),p.getTotalElements(),p.getTotalPages(),"pessoa","asc");}
 private void validar(RelatorioContribuicaoFiltro f){if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória");if(f.dataInicio()!=null&&f.dataFim()!=null&&f.dataFim().isBefore(f.dataInicio()))throw new IllegalArgumentException("Data final não pode ser anterior à data inicial");seguranca.validarAcesso(f.organizacaoUuid());} private String tipo(RelatorioContribuicaoFiltro f){return f.tipo()==null?null:f.tipo().name();} private String pessoa(RelatorioContribuicaoFiltro f){return f.pessoa()==null||f.pessoa().isBlank()?null:f.pessoa().trim();} private int pagina(RelatorioContribuicaoFiltro f){return Math.max(0,f.pagina());} private int tamanho(RelatorioContribuicaoFiltro f){return Math.max(10,Math.min(100,f.tamanho()));}
}
